import json

def main():
    url = "https://httpbin.org/post"
    headers = {
        "X-Test-Header": "value123",
        "Content-Type": "application/json"
    }
    payload = {
        "message": "Hello from Python",
        "count": 42
    }

    try:
        response = requests.post(url, headers=headers, data=json.dumps(payload))
        print(response.status_code)
