pure func parseLine(s: string) -> int {
  let t = trim(s);
  if t == "" then 0
  else match stringToInt(t) {
    Some(n) => n,
    None => 0
  }
}

pure func sumLines(lines: [string]) -> int =
  match lines {
    [] => 0,
    line :: rest => parseLine(line) + sumLines(rest)
  }

export func main() -> () ! {IO, FS, Env} {
  let args = getArgs();
  match args {
    filename :: _ => {
      let content = readFile(filename);
      let lines = split(content, "\n");
      println(show(sumLines(lines)))
    },
    [] => println("0")
  }
}

