module benchmark/solution

import std/fs (readFile, writeFile)
import std/json (decode, getString, getInt, getArray, allStrings, Json)
import std/list (length)
import std/string (chars)
import std/option (Some, None)
import std/result (Result, Ok, Err)

type Config = {app_name: string, version: string, port: int, features: [string]}

pure func countDotsChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == "." then 1 else 0) + countDotsChars(rest)
  }

pure func countDots(s: string) -> int =
  countDotsChars(chars(s))

pure func validateConfig(appName: string, version: string, port: int, features: [string]) -> Result[Config, string] =
  if port < 1024 || port > 65535 then Err("Invalid port")
  else if countDots(version) != 2 then Err("Invalid version")
  else if length(features) == 0 then Err("Features list is empty")
  else Ok({app_name: appName, version: version, port: port, features: features})

pure func parseConfig(json: Json) -> Result[Config, string] =
  match getString(json, "app_name") {
    Some(appName) => match getString(json, "version") {
      Some(version) => match getInt(json, "port") {
        Some(port) => match getArray(json, "features") {
          Some(arr) => match allStrings(arr) {
            Some(features) => validateConfig(appName, version, port, features),
            None => Err("Invalid features")
          },
          None => Err("Missing features")
        },
        None => Err("Missing port")
      },
      None => Err("Missing version")
    },
    None => Err("Missing app_name")
  }

func createConfigFile() -> () ! {FS} =
  writeFile("app_config.json", "{\"app_name\":\"MyApp\",\"version\":\"1.0.0\",\"port\":8080,\"features\":[\"logging\",\"auth\",\"api\"]}")

func loadAndValidateConfig(path: string) -> Result[Config, string] ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(json) => parseConfig(json),
    Err(msg) => Err(msg)
  }
}

export func main() -> () ! {IO, FS} {
  createConfigFile();
  match loadAndValidateConfig("app_config.json") {
    Ok(cfg) => println("Loaded ${cfg.app_name} v${cfg.version} on port ${cfg.port} with ${length(cfg.features)} features"),
    Err(msg) => println("Error: ${msg}")
  }
}

