package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func main() {
	// Create the JSON config file
	configData := Config{
		AppName:  "MyApp",
		Version:  "1.0.0",
		Port:     8080,
		Features: []string{"logging", "auth", "api"},
	}

	// Marshal to JSON
	jsonData, err := json.MarshalIndent(configData, "", "  ")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error marshaling JSON: %v\n", err)
		os.Exit(1)
	}

	// Write to file
	err = os.WriteFile("app_config.json", jsonData, 0644)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error writing config file: %v\n", err)
		os.Exit(1)
	}

	// Load and validate the config
	config, err := loadAndValidateConfig("app_config.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	// Print the result
	fmt.Printf("Loaded %s v%s on port %d with %d features\n",
		config.AppName, config.Version, config.Port, len(config.Features))
}

func loadAndValidateConfig(filename string) (*Config, error) {
	// Read the JSON file
	fileContent, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("failed to read config file: %w", err)
	}

	// Parse the JSON content
	var config Config
	err = json.Unmarshal(fileContent, &config)
	if err != nil {
		return nil, fmt.Errorf("failed to parse JSON: %w", err)
	}

	// Validate port is between 1024 and 65535
	if config.Port < 1024 || config.Port > 65535 {
		return nil, fmt.Errorf("port %d is out of valid range [1024, 65535]", config.Port)
	}

	// Validate version contains exactly two dots (X.Y.Z format)
	dotCount := strings.Count(config.Version, ".")
	if dotCount != 2 {
		return nil, fmt.Errorf("version %q must be in X.Y.Z format with exactly two dots", config.Version)
	}

	// Validate that features list is not empty
	if len(config.Features) == 0 {
		return nil, fmt.Errorf("features list cannot be empty")
	}

	return &config, nil
}

