import fs from 'fs';
import path from 'path';

function validateConfig(config) {
  // Validate port is between 1024 and 65535
  if (typeof config.port !== 'number' || config.port < 1024 || config.port > 65535) {
    throw new Error(`Invalid port: ${config.port}. Must be between 1024 and 65535.`);
  }

  // Validate version contains exactly two dots (X.Y.Z format)
  const versionDots = (config.version.match(/\./g) || []).length;
  if (versionDots !== 2) {
    throw new Error(`Invalid version format: ${config.version}. Must be in X.Y.Z format.`);
  }

  // Validate features list is not empty
  if (!Array.isArray(config.features) || config.features.length === 0) {
    throw new Error('Features list must not be empty.');
  }

  return true;
}

function loadAndValidateConfig(configPath) {
  const content = fs.readFileSync(configPath, 'utf-8');
  const config = JSON.parse(content);
  validateConfig(config);
  return config;
}

function main() {
  // Create app_config.json
  const configData = {
    app_name: 'MyApp',
    version: '1.0.0',
    port: 8080,
    features: ['logging', 'auth', 'api']
  };

  const configPath = path.join(process.cwd(), 'app_config.json');
  fs.writeFileSync(configPath, JSON.stringify(configData, null, 2));

  // Load and validate the config
  const config = loadAndValidateConfig(configPath);

  // Print result in the required format
  const output = `Loaded ${config.app_name} v${config.version} on port ${config.port} with ${config.features.length} features`;
  console.log(output);
}

main();

