from __future__ import annotations

import json
from pathlib import Path


CONFIG_PATH = Path("app_config.json")
CONFIG_DATA = {
    "app_name": "MyApp",
    "version": "1.0.0",
    "port": 8080,
    "features": ["logging", "auth", "api"],
}


class ConfigError(ValueError):
    pass


def write_default_config(path: Path) -> None:
    path.write_text(json.dumps(CONFIG_DATA, indent=2), encoding="utf-8")


def load_and_validate_config(path: Path) -> dict[str, object]:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ConfigError(f"Config file not found: {path}") from exc
    except json.JSONDecodeError as exc:
        raise ConfigError(f"Invalid JSON in config file: {path}") from exc

    if not isinstance(data, dict):
        raise ConfigError("Config must be a JSON object")

    app_name = data.get("app_name")
    version = data.get("version")
    port = data.get("port")
    features = data.get("features")

    if not isinstance(app_name, str) or not app_name:
        raise ConfigError("Invalid app_name")
    if not isinstance(version, str) or version.count(".") != 2:
        raise ConfigError("Invalid version format")
    if not isinstance(port, int) or not (1024 <= port <= 65535):
        raise ConfigError("Invalid port")
    if not isinstance(features, list) or not features:
        raise ConfigError("Invalid features")

    return {
        "app_name": app_name,
        "version": version,
        "port": port,
        "features": features,
    }


def main() -> None:
    write_default_config(CONFIG_PATH)
    config = load_and_validate_config(CONFIG_PATH)
    print(
        f"Loaded {config['app_name']} v{config['version']} "
        f"on port {config['port']} with {len(config['features'])} features"
    )


if __name__ == "__main__":
    main()

