module benchmark/solution

import std/io (println)

export type BST = Leaf | Node(BST, int, BST)

export func insert(t: BST, x: int) -> BST =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(l, v, r) =>
      if x < v then Node(insert(l, x), v, r)
      else if x > v then Node(l, v, insert(r, x))
      else Node(l, v, r)
  }

export func contains(t: BST, x: int) -> bool =
  match t {
    Leaf => false,
    Node(l, v, r) =>
      if x == v then true
      else if x < v then contains(l, x)
      else contains(r, x)
  }

export func size(t: BST) -> int =
  match t {
    Leaf => 0,
    Node(l, _, r) => 1 + size(l) + size(r)
  }

export func isBST(t: BST, lo: int, hi: int) -> bool =
  match t {
    Leaf => true,
    Node(l, v, r) =>
      if v > lo && v < hi then
        isBST(l, lo, v) && isBST(r, v, hi)
      else
        false
  }

export func insertPreservesBST(x: int) -> bool {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  let t2 = insert(t, x);
  isBST(t2, -999999, 999999)
}

export func insertThenFind(x: int) -> bool {
  let t = insert(Leaf, x);
  contains(t, x)
}

export func main() -> () ! {IO} {
  let t = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(t)));
  println(show(contains(t, 3)));
  println(show(contains(t, 4)));
  println(show(isBST(t, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

