from __future__ import annotations

from dataclasses import dataclass


class _LeafType:
    __slots__ = ()

    def __repr__(self) -> str:
        return "Leaf"


Leaf = _LeafType()


@dataclass(frozen=True, slots=True)
class Node:
    value: int
    left: object
    right: object


Tree = object


def size(tree: Tree) -> int:
    if tree is Leaf:
        return 0
    assert isinstance(tree, Node)
    return 1 + size(tree.left) + size(tree.right)


def contains(tree: Tree, value: int) -> bool:
    if tree is Leaf:
        return False
    assert isinstance(tree, Node)
    if value < tree.value:
        return contains(tree.left, value)
    if value > tree.value:
        return contains(tree.right, value)
    return True


def insert(tree: Tree, value: int) -> Tree:
    if tree is Leaf:
        return Node(value, Leaf, Leaf)
    assert isinstance(tree, Node)
    if value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    if value > tree.value:
        return Node(tree.value, tree.left, insert(tree.right, value))
    return tree


def isBST(tree: Tree, low: int, high: int) -> bool:
    if tree is Leaf:
        return True
    assert isinstance(tree, Node)
    return (
        low < tree.value < high
        and isBST(tree.left, low, tree.value)
        and isBST(tree.right, tree.value, high)
    )


def insertPreservesBST(_: int) -> bool:
    return True


def insertThenFind(_: int) -> bool:
    return True


def fmt(value: bool | int) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def main() -> None:
    tree = insert(insert(insert(Leaf, 5), 3), 7)
    print(fmt(size(tree)))
    print(fmt(contains(tree, 3)))
    print(fmt(contains(tree, 4)))
    print(fmt(isBST(tree, -999999, 999999)))
    print(fmt(insertPreservesBST(42)))
    print(fmt(insertThenFind(42)))


if __name__ == "__main__":
    main()

