module benchmark/solution

import std/io (println)
import std/string (chars, length, stringToInt, substring)
import std/list (length as listLength)
import std/option (Option, Some, None)

func encodeHelper(cs: [string], current: string, count: int) -> string =
  match cs {
    [] => if count == 0 then "" else "${show(count)}${current}",
    c :: rest =>
      if count == 0 then encodeHelper(rest, c, 1)
      else if c == current then encodeHelper(rest, current, count + 1)
      else "${show(count)}${current}${encodeHelper(rest, c, 1)}"
  }

export func encode(s: string) -> string =
  encodeHelper(chars(s), "", 0)

func parseDigits(cs: [string], acc: int) -> {count: int, rest: [string]} =
  match cs {
    [] => {count: acc, rest: []},
    c :: rest => {
      let isDigit = c == "0" || c == "1" || c == "2" || c == "3" || c == "4" || c == "5" || c == "6" || c == "7" || c == "8" || c == "9";
      if isDigit then
        match stringToInt(c) {
          Some(d) => parseDigits(rest, acc * 10 + d),
          None => {count: acc, rest: cs}
        }
      else {count: acc, rest: cs}
    }
  }

func repeatStr(s: string, n: int) -> string =
  if n <= 0 then "" else "${s}${repeatStr(s, n - 1)}"

func decodeHelper(cs: [string]) -> string =
  match cs {
    [] => "",
    _ => {
      let parsed = parseDigits(cs, 0);
      match parsed.rest {
        [] => "",
        ch :: more => "${repeatStr(ch, parsed.count)}${decodeHelper(more)}"
      }
    }
  }

export func decode(s: string) -> string =
  decodeHelper(chars(s))

export func roundtrip(s: string) -> bool =
  decode(encode(s)) == s

export func singleCharEncode(s: string) -> string =
  encode(s)

export func main() -> () ! {IO} {
  println(encode("aaabbc"));
  println(encode("xyz"));
  println(decode("3a2b1c"));
  println(decode("1x1y1z"));
  println(show(roundtrip("hello")));
  println(singleCharEncode("q"))
}

