def encode(s: str) -> str:
    if not s:
        return ""

    encoded_chars = []
    count = 0
    current_char = ''

    for char in s:
        if char == current_char:
            count += 1
        else:
            if current_char:
                encoded_chars.append(str(count) + current_char)
            current_char = char
            count = 1

    # Append the last sequence
    if current_char:
        encoded_chars.append(str(count) + current_char)

    return "".join(encoded_chars)

def decode(s: str) -> str:
    if not s:
        return ""

    decoded_chars = []
    i = 0
    while i < len(s):
        count_str = ""
        while s[i].isdigit():
            count_str += s[i]
            i += 1
        count = int(count_str)
        char = s[i]
        decoded_chars.append(char * count)
        i += 1
    return "".join(decoded_chars)

def roundtrip(s: str) -> bool:
    return decode(encode(s)) == s

def singleCharEncode(char: str) -> bool:
    return encode(char) == "1" + char

if __name__ == "__main__":
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(str(roundtrip("hello")).lower())
    print(str(singleCharEncode("q")).lower())

