module benchmark/solution

import std/string (startsWith, substring, length as strLength)

type RomanEntry = {value: int, symbol: string}

pure func romanTable() -> [RomanEntry] =
  [
    {value: 1000, symbol: "M"},
    {value: 900, symbol: "CM"},
    {value: 500, symbol: "D"},
    {value: 400, symbol: "CD"},
    {value: 100, symbol: "C"},
    {value: 90, symbol: "XC"},
    {value: 50, symbol: "L"},
    {value: 40, symbol: "XL"},
    {value: 10, symbol: "X"},
    {value: 9, symbol: "IX"},
    {value: 5, symbol: "V"},
    {value: 4, symbol: "IV"},
    {value: 1, symbol: "I"}
  ]

pure func toRomanWith(n: int, table: [RomanEntry]) -> string =
  if n <= 0 then ""
  else match table {
    [] => "",
    entry :: rest =>
      if n >= entry.value
      then "${entry.symbol}${toRomanWith(n - entry.value, entry :: rest)}"
      else toRomanWith(n, rest)
  }

export func toRoman(n: int) -> string =
  if n >= 1 && n <= 3999 then toRomanWith(n, romanTable()) else ""

pure func parseRomanWith(s: string, table: [RomanEntry]) -> int =
  if s == "" then 0
  else match table {
    [] => 0,
    entry :: rest =>
      if startsWith(s, entry.symbol)
      then entry.value + parseRomanWith(substring(s, strLength(entry.symbol), strLength(s)), entry :: rest)
      else parseRomanWith(s, rest)
  }

pure func parseRomanValue(s: string) -> int =
  parseRomanWith(s, romanTable())

export func fromRoman(s: string) -> int {
  let value = parseRomanValue(s);
  if value >= 1 && value <= 3999 && toRoman(value) == s then value else 0
}

export func roundtrip(n: int) -> bool =
  if n >= 1 && n <= 3999 then fromRoman(toRoman(n)) == n else true

export func distinctEncoding(a: int, b: int) -> bool =
  if a >= 1 && a <= 3999 && b >= 1 && b <= 3999 && a != b
  then toRoman(a) != toRoman(b)
  else true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

export type SSet = SNil | SCons(int, SSet)

export func sLength(s: SSet) -> int ! {} {
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }
}

export func isSorted(s: SSet) -> bool ! {} {
  match s {
    SNil => true,
    SCons(x, rest) => match rest {
      SNil => true,
      SCons(y, _) => if x < y then isSorted(rest) else false
    }
  }
}

export func sMerge(a: SSet, b: SSet) -> SSet ! {} {
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if x > y then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }
}

export func sIntersect(a: SSet, b: SSet) -> SSet ! {} {
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if x > y then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }
}

func elemsToStr(s: SSet) -> string ! {} {
  match s {
    SNil => "",
    SCons(x, rest) => match rest {
      SNil => show(x),
      _ => "${show(x)}, ${elemsToStr(rest)}"
    }
  }
}

export func toStr(s: SSet) -> string ! {} {
  "{${elemsToStr(s)}}"
}

export func mergePreservesSorted(a: SSet, b: SSet) -> bool ! {} {
  if isSorted(a) && isSorted(b) then isSorted(sMerge(a, b)) else true
}

export func intersectPreservesSorted(a: SSet, b: SSet) -> bool ! {} {
  if isSorted(a) && isSorted(b) then isSorted(sIntersect(a, b)) else true
}

export func inclusionExclusion(a: SSet, b: SSet) -> bool ! {} {
  if isSorted(a) && isSorted(b)
  then sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)
  else true
}

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  println(toStr(sMerge(a, b)));
  println(toStr(sIntersect(a, b)));
  println(show(sLength(sMerge(a, b))));
  println(show(isSorted(sMerge(a, b))));
  println(show(mergePreservesSorted(a, b)));
  println(show(inclusionExclusion(a, b)))
}

