from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class _SNil:
    pass


@dataclass(frozen=True)
class SCons:
    head: int
    tail: SortedSet


type SortedSet = _SNil | SCons

SNil = _SNil()


def sLength(xs: SortedSet) -> int:
    match xs:
        case _SNil():
            return 0
        case SCons(_, tail):
            return 1 + sLength(tail)


def to_list(xs: SortedSet) -> list[int]:
    match xs:
        case _SNil():
            return []
        case SCons(head, tail):
            return [head, *to_list(tail)]


def toStr(xs: SortedSet) -> str:
    return "[" + ",".join(str(value) for value in to_list(xs)) + "]"


def isSorted(xs: SortedSet) -> bool:
    match xs:
        case _SNil():
            return True
        case SCons(_, _SNil()):
            return True
        case SCons(head, SCons(next_head, tail)):
            return head < next_head and isSorted(SCons(next_head, tail))


def sMerge(left: SortedSet, right: SortedSet) -> SortedSet:
    match left, right:
        case _SNil(), _:
            return right
        case _, _SNil():
            return left
        case SCons(l_head, l_tail), SCons(r_head, r_tail):
            if l_head < r_head:
                return SCons(l_head, sMerge(l_tail, right))
            if l_head > r_head:
                return SCons(r_head, sMerge(left, r_tail))
            return SCons(l_head, sMerge(l_tail, r_tail))


def sIntersect(left: SortedSet, right: SortedSet) -> SortedSet:
    match left, right:
        case _SNil(), _:
            return SNil
        case _, _SNil():
            return SNil
        case SCons(l_head, l_tail), SCons(r_head, r_tail):
            if l_head < r_head:
                return sIntersect(l_tail, right)
            if l_head > r_head:
                return sIntersect(left, r_tail)
            return SCons(l_head, sIntersect(l_tail, r_tail))


def mergePreservesSorted(left: SortedSet, right: SortedSet) -> bool:
    return isSorted(left) and isSorted(right) and isSorted(sMerge(left, right))


def intersectPreservesSorted(left: SortedSet, right: SortedSet) -> bool:
    return isSorted(left) and isSorted(right) and isSorted(sIntersect(left, right))


def inclusionExclusion(left: SortedSet, right: SortedSet) -> bool:
    return (
        sLength(sMerge(left, right)) + sLength(sIntersect(left, right))
        == sLength(left) + sLength(right)
    )


def bool_str(value: bool) -> str:
    return "true" if value else "false"


def main() -> None:
    first = SCons(1, SCons(3, SCons(5, SNil)))
    second = SCons(2, SCons(3, SCons(4, SNil)))
    merged = sMerge(first, second)

    print(toStr(merged))
    print(toStr(sIntersect(first, second)))
    print(sLength(merged))
    print(bool_str(isSorted(merged)))
    print(bool_str(mergePreservesSorted(first, second)))
    print(bool_str(inclusionExclusion(first, second)))


if __name__ == "__main__":
    main()

