import std/fs (writeFile, readFile)
import std/string (split, trim, stringToInt, contains)
import std/list (length)
import std/json (encode, jo, ja, kv, js, jnum)
import std/option (Option, Some, None)

type Row = Row({name: string, age: int, email: string})

func parseRow(line: string) -> Option[Row] {
  let fields = split(line, ",");
  match fields {
    name :: age :: email :: [] => {
      let n = trim(name);
      let a = trim(age);
      let e = trim(email);
      match stringToInt(a) {
        Some(ageNum) =>
          if ageNum > 0 && contains(e, "@")
          then Some(Row({name: n, age: ageNum, email: e}))
          else None,
        None => None
      }
    },
    _ => None
  }
}

func parseRows(lines: [string]) -> [Row] {
  match lines {
    [] => [],
    line :: rest => {
      let t = trim(line);
      if t == ""
      then parseRows(rest)
      else match parseRow(t) {
        Some(r) => r :: parseRows(rest),
        None => parseRows(rest)
      }
    }
  }
}

func skipHeader(lines: [string]) -> [string] {
  match lines {
    [] => [],
    _ :: rest => rest
  }
}

func rowToJson(r: Row) {
  match r {
    Row(rec) => jo([
      kv("name", js(rec.name)),
      kv("age", jnum(rec.age)),
      kv("email", js(rec.email))
    ])
  }
}

func rowsToJsonList(rs: [Row]) {
  match rs {
    [] => [],
    r :: rest => rowToJson(r) :: rowsToJsonList(rest)
  }
}

