package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email"`
}

func main() {
	// Create input CSV file
	csvContent := "name,age,email\nAlice,30,alice@example.com\nBob,25,bob@example.com\nCarol,35,carol@example.com\n"
	err := os.WriteFile("users.csv", []byte(csvContent), 0644)
	if err != nil {
		fmt.Printf("Error writing CSV file: %v\n", err)
		return
	}

	// Read and parse CSV file
	file, err := os.Open("users.csv")
	if err != nil {
		fmt.Printf("Error opening CSV file: %v\n", err)
		return
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	var headers []string
	var validUsers []User
	lineNum := 0

	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		fields := strings.Split(line, ",")

		if lineNum == 1 {
			headers = fields
			continue
		}

		// Validate row
		if len(fields) != len(headers) {
			continue
		}

		user := User{}
		valid := true

		for i, header := range headers {
			switch header {
			case "name":
				user.Name = fields[i]
			case "age":
				age, err := strconv.Atoi(fields[i])
				if err != nil || age <= 0 {
					valid = false
					break
				}
				user.Age = age
			case "email":
				if !strings.Contains(fields[i], "@") {
					valid = false
					break
				}
				user.Email = fields[i]
			}
		}

		if valid {
			validUsers = append(validUsers, user)
		}
	}

	if err := scanner.Err(); err != nil {
		fmt.Printf("Error reading CSV file: %v\n", err)
		return
	}

	// Convert to JSON
	jsonData, err := json.Marshal(validUsers)
	if err != nil {
		fmt.Printf("Error marshaling JSON: %v\n", err)
		return
	}

	// Write JSON to file
	err = os.WriteFile("users.json", jsonData, 0644)
	if err != nil {
		fmt.Printf("Error writing JSON file: %v\n", err)
		return
	}

	// Print success message
	fmt.Printf("Converted %d valid rows to users.json\n", len(validUsers))
}

