module benchmark/solution

pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  queue ++ [x]

pure func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

pure func neighbors(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    (n, ns) :: rest => if node == n then ns else neighbors(node, rest)
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int], order: [int]) -> [int] =
  match queue {
    [] => order,
    node :: rest => if contains(node, visited) then
      bfsLoop(graph, rest, visited, order)
    else {
      let ns = neighbors(node, graph);
      let nextQueue = enqueueAll(ns, rest);
      let nextVisited = node :: visited;
      let nextOrder = enqueue(node, order);
      bfsLoop(graph, nextQueue, nextVisited, nextOrder)
    }
  }

pure func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [], [])

func printNodes(nodes: [int]) -> () ! {IO} =
  match nodes {
    [] => (),
    x :: rest => {
      println(show(x));
      printNodes(rest)
    }
  }

