  match split(line, " ") {
    _ :: _ :: level :: _ => level,
    _ => ""
  }

pure func countLevel(lines: [string], target: string) -> int =
  match lines {
    [] => 0,
    line :: rest => if getLevel(line) == target then 1 + countLevel(rest, target) else countLevel(rest, target)
  }

pure func percentage(count: int, total: int) -> int =
  if total == 0 then 0 else (count * 100) / total

pure func lastPart(parts: [string]) -> string =
  match parts {
    [] => "",
    x :: rest => match rest {
      [] => x,
      _ => lastPart(rest)
    }
  }

pure func allLowerLetters(cs: [string]) -> bool =
  match cs {
    [] => true,
    c :: rest => if c >= "a" && c <= "z" then allLowerLetters(rest) else false
  }

pure func isUsername(s: string) -> bool =
  match chars(s) {
    [] => false,
    cs => allLowerLetters(cs)
  }

pure func userFromLine(line: string) -> [string] {
  let candidate = trim(lastPart(split(line, ":")));
  if isUsername(candidate) then [candidate] else []
}

pure func collectUsers(lines: [string]) -> [string] =
  match lines {
    [] => [],
    line :: rest => listConcat(userFromLine(line), collectUsers(rest))
  }

pure func memberString(x: string, xs: [string]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else memberString(x, rest)
  }

pure func uniqueStrings(xs: [string]) -> [string] =
  match xs {
    [] => [],
    x :: rest => if memberString(x, rest) then uniqueStrings(rest) else x :: uniqueStrings(rest)
  }

pure func cmpString(a: string, b: string) -> int =
