from __future__ import annotations
from dataclasses import dataclass

@dataclass
class Num:
    n: int

@dataclass
class Var:
    s: str

@dataclass
class Add:
    e1: Expr
    e2: Expr

@dataclass
class Mul:
    e1: Expr
    e2: Expr

@dataclass
class Let:
    s: str
    e1: Expr
    e2: Expr

type Expr = Num | Var | Add | Mul | Let

def lookup(name: str, env: list[tuple[str, int]]) -> int:
    for n, v in reversed(env):
        if n == name:
            return v
    raise ValueError(f"Variable {name} not found")

def eval(expr: Expr, env: list[tuple[str, int]]) -> int:
    match expr:
        case Num(n):
            return n
        case Var(s):
            return lookup(s, env)
        case Add(e1, e2):
            return eval(e1, env) + eval(e2, env)
        case Mul(e1, e2):
            return eval(e1, env) * eval(e2, env)
        case Let(s, e1, e2):
            val = eval(e1, env)
            return eval(e2, env + [(s, val)])

def main():
    ast = Let("x", Num(5), 
              Let("y", Add(Var("x"), Num(3)), 
                  Mul(Var("x"), Var("y"))))
    print(eval(ast, []))

