package main

import "fmt"

type Tree interface {
	isTree()
}

type Leaf struct {
	Value int
}

type Node struct {
	Left  Tree
	Value int
	Right Tree
}

func (Leaf) isTree() {}

func (Node) isTree() {}

func treeSum(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return t.Value
	case Node:
		return treeSum(t.Left) + t.Value + treeSum(t.Right)
	default:
		panic("exhaustiveness check failed: unknown tree variant")
	}
}

func findMax(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return t.Value
	case Node:
		leftMax := findMax(t.Left)
		rightMax := findMax(t.Right)

		// Nested matching with guards: choose among the node value and child maxima.
		switch {
		case leftMax >= t.Value && leftMax >= rightMax:
			return leftMax
		case rightMax >= t.Value && rightMax >= leftMax:
			return rightMax
		default:
			return t.Value
		}
	default:
		panic("exhaustiveness check failed: unknown tree variant")
	}
}

func main() {
	tree := Node{
		Left:  Leaf{Value: 1},
		Value: 5,
		Right: Node{
			Left:  Leaf{Value: 3},
			Value: 7,
			Right: Leaf{Value: 2},
		},
	}

	fmt.Printf("Sum: %d\n", treeSum(tree))
	fmt.Printf("Max: %d\n", findMax(tree))
}

