// Define algebraic data type Tree using classes
class Leaf {
  constructor(value) {
    this.value = value;
  }
}

class Node {
  constructor(left, value, right) {
    this.left = left;
    this.value = value;
    this.right = right;
  }
}

// Tree sum using pattern matching
function tree_sum(tree) {
  if (tree instanceof Leaf) {
    // Match Leaf(v): return v
    return tree.value;
  } else if (tree instanceof Node) {
    // Match Node(l, v, r): return tree_sum(l) + v + tree_sum(r)
    return tree_sum(tree.left) + tree.value + tree_sum(tree.right);
  }
}

// Find max using pattern matching with nested patterns and guards
function find_max(tree) {
  if (tree instanceof Leaf) {
    // Match Leaf(v): return v
    return tree.value;
  } else if (tree instanceof Node) {
    // Match Node with guards to find maximum value in tree
    const left_max = find_max(tree.left);
    const right_max = find_max(tree.right);
    return Math.max(left_max, tree.value, right_max);
  }
}

// Create sample tree: Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
const sampleTree = new Node(
  new Leaf(1),
  5,
  new Node(
    new Leaf(3),
    7,
    new Leaf(2)
  )
);

// Calculate and print results
