def run_length_encode(data: list[str]) -> list[tuple[int, str]]:
    if not data:
        return []

    encoded_data = []
    i = 0
    while i < len(data):
        current_char = data[i]
        count = 0
        j = i
        while j < len(data) and data[j] == current_char:
            count += 1
            j += 1
        encoded_data.append((count, current_char))
        i = j
    return encoded_data

