	isEvent()
}

// Call event variant
type Call struct {
	Floor int
}

func (Call) isEvent() {}

// Tick event variant
type Tick struct{}

func (Tick) isEvent() {}

// Arrive event variant
type Arrive struct{}

func (Arrive) isEvent() {}

// Transition function: state + event -> new state
func transition(state State, event Event) State {
	switch s := state.(type) {
	case Idle:
		switch e := event.(type) {
		case Call:
			if e.Floor == s.Floor {
				return DoorOpen{Floor: s.Floor, Timer: 3}
			}
			return Moving{CurrentFloor: s.Floor, TargetFloor: e.Floor}
		case Tick:
			return s
		case Arrive:
			return s
		}
	case Moving:
		switch event.(type) {
		case Call:
			return s
		case Tick:
			return s
		case Arrive:
			return DoorOpen{Floor: s.TargetFloor, Timer: 3}
		}
	case DoorOpen:
		switch event.(type) {
		case Call:
			return s
		case Tick:
			if s.Timer > 1 {
				return DoorOpen{Floor: s.Floor, Timer: s.Timer - 1}
			}
			return Idle{Floor: s.Floor}
		case Arrive:
			return s
		}
	}
	return state
}

