class Idle {
  constructor(floor) {
    this.type = 'Idle';
    this.floor = floor;
  }
}

class Moving {
  constructor(currentFloor, targetFloor) {
    this.type = 'Moving';
    this.currentFloor = currentFloor;
    this.targetFloor = targetFloor;
  }
}

class DoorOpen {
  constructor(floor, timer) {
    this.type = 'DoorOpen';
    this.floor = floor;
    this.timer = timer;
  }
}

// Event ADT variants
class Call {
  constructor(floor) {
    this.type = 'Call';
    this.floor = floor;
  }
}

class Tick {
  constructor() {
    this.type = 'Tick';
  }
}

class Arrive {
  constructor() {
    this.type = 'Arrive';
  }
}

// Transition function with exhaustive pattern matching
function transition(state, event) {
  // Idle + Call
  if (state.type === 'Idle' && event.type === 'Call') {
    const { floor: currentFloor } = state;
    const { floor: targetFloor } = event;
    if (targetFloor === currentFloor) {
      return new DoorOpen(currentFloor, 3);
    } else {
      return new Moving(currentFloor, targetFloor);
    }
  }

  // Moving + Tick
  if (state.type === 'Moving' && event.type === 'Tick') {
    return state;
  }

  // Moving + Arrive
  if (state.type === 'Moving' && event.type === 'Arrive') {
    return new DoorOpen(state.targetFloor, 3);
  }

  // DoorOpen + Tick
  if (state.type === 'DoorOpen' && event.type === 'Tick') {
    const { floor, timer } = state;
    if (timer > 1) {
      return new DoorOpen(floor, timer - 1);
    } else {
      return new Idle(floor);
    }
  }

  // Any other combination: return state unchanged
  return state;
}

// Display function
function display(state) {
  if (state.type === 'Idle') {
    return `IDLE @ floor ${state.floor}`;
  }
  if (state.type === 'Moving') {
    return `MOVING ${state.currentFloor} -> ${state.targetFloor}`;
  }
  if (state.type === 'DoorOpen') {
    return `DOOR_OPEN @ floor ${state.floor} (${state.timer}sec)`;
  }
}

// Main simulation
function main() {
