package main

import (
	"fmt"
)

// State represents the vending machine state
type State interface {
	isState()
}

type Idle struct{}

func (Idle) isState() {}

type HasCredit struct {
	cents int
}

func (HasCredit) isState() {}

type Dispensing struct {
	change int
}

func (Dispensing) isState() {}

// Event represents an event
type Event interface {
	isEvent()
}

type Insert struct {
	cents int
}

func (Insert) isEvent() {}

type Select struct {
	code int
}

func (Select) isEvent() {}

type DispenseDone struct{}

func (DispenseDone) isEvent() {}

// Result represents either Ok(State) or Err(string)
type Result struct {
	ok    bool
	state State
	err   string
}

func Ok(state State) Result {
	return Result{ok: true, state: state}
}

func Err(reason string) Result {
	return Result{ok: false, err: reason}
}

// price returns the price of an item by code
func price(code int) int {
	switch code {
	case 1:
		return 125 // cola
	case 2:
		return 75 // chips
	case 3:
		return 100 // water
	default:
		return -1
	}
}

// step transitions the state machine
func step(state State, event Event) Result {
	switch s := state.(type) {
	case Idle:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: e.cents})
		case Select:
			return Err("no_credit")
		case DispenseDone:
			return Err("not_dispensing")
		}
	case HasCredit:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: s.cents + e.cents})
		case Select:
			p := price(e.code)
			if p == -1 {
				return Err("unknown_item")
			}
			if s.cents < p {
				return Err("insufficient_funds")
			}
			return Ok(Dispensing{change: s.cents - p})
		case DispenseDone:
			return Err("not_dispensing")
		}
	case Dispensing:
		switch event.(type) {
		case Insert:
			return Err("busy")
		case Select:
			return Err("busy")
		case DispenseDone:
			return Ok(Idle{})
		}
	}
	return Err("unknown_state")
}

// formatState returns the string representation of a state
func formatState(state State) string {
	switch s := state.(type) {
	case Idle:
		return "IDLE"
	case HasCredit:
		return fmt.Sprintf("CREDIT(%d)", s.cents)
	case Dispensing:
		return fmt.Sprintf("DISPENSING(%d)", s.change)
	}
	return "UNKNOWN"
}

func main() {
	state := State(Idle{})

	events := []Event{
		Insert{cents: 50},
		Select{code: 1},
		Insert{cents: 100},
		Select{code: 1},
		Insert{cents: 50},
		DispenseDone{},
		Select{code: 2},
		Insert{cents: 100},
		Select{code: 2},
		DispenseDone{},
	}

	for _, event := range events {
		result := step(state, event)
		if result.ok {
			fmt.Printf("ok: %s\n", formatState(result.state))
			state = result.state
		} else {
			fmt.Printf("err: %s\n", result.err)
		}
	}
}

