from dataclasses import dataclass

# State algebraic data type
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

type State = Idle | HasCredit | Dispensing

# Event algebraic data type
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

type Event = Insert | Select | DispenseDone

# Result algebraic data type
@dataclass
class Ok:
    state: State

@dataclass
class Err:
    reason: str

type Result = Ok | Err

def get_price(code: int) -> int | None:
    """Get price for item code. 1=cola(125), 2=chips(75), 3=water(100)"""
    match code:
        case 1:
            return 125
        case 2:
            return 75
        case 3:
            return 100
        case _:
            return None

def step(state: State, event: Event) -> Result:
    """Transition function: step(state, event) -> Result<State, String>"""
    match (state, event):
        # Idle state transitions
        case (Idle(), Insert(n)):
            return Ok(HasCredit(n))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        # HasCredit state transitions
        case (HasCredit(c), Insert(n)):
            return Ok(HasCredit(c + n))
        case (HasCredit(c), Select(code)):
            price = get_price(code)
            if price is None:
                return Err("unknown_item")
            elif c < price:
                return Err("insufficient_funds")
            else:
                return Ok(Dispensing(c - price))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        # Dispensing state transitions
        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(_), DispenseDone()):
            return Ok(Idle())

        case _:
            return Err("unknown_state")

def format_result(result: Result) -> str:
    """Format result for output"""
    match result:
        case Ok(state):
            match state:
                case Idle():
                    return "ok: IDLE"
                case HasCredit(n):
                    return f"ok: CREDIT({n})"
                case Dispensing(ch):
                    return f"ok: DISPENSING({ch})"
        case Err(reason):
            return f"err: {reason}"

def main() -> None:
    state: State = Idle()

    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    for event in events:
        result = step(state, event)
        print(format_result(result))

        # Update state if transition was successful
        match result:
            case Ok(new_state):
                state = new_state
            case Err(_):
                # Keep previous state on error
                pass

if __name__ == "__main__":
    main()

