package main

import (
	"fmt"
	"strings"
)

// Tree represents a binary tree with Leaf and Node variants
type Tree interface {
	isTree()
}

type Leaf struct {
	Value int
}

func (Leaf) isTree() {}

type Node struct {
	Left  Tree
	Value int
	Right Tree
}

func (Node) isTree() {}

// mapTree recursively applies a function to all values in the tree
func mapTree(fn func(int) int, tree Tree) Tree {
	switch t := tree.(type) {
	case Leaf:
		return Leaf{Value: fn(t.Value)}
	case Node:
		return Node{
			Left:  mapTree(fn, t.Left),
			Value: fn(t.Value),
			Right: mapTree(fn, t.Right),
		}
	}
	return tree
}

// foldTree performs an in-order fold over tree values
func foldTree(fn func(int, int) int, acc int, tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return fn(acc, t.Value)
	case Node:
		leftAcc := foldTree(fn, acc, t.Left)
		nodeAcc := fn(leftAcc, t.Value)
		return foldTree(fn, nodeAcc, t.Right)
	}
	return acc
}

// treeToList returns an in-order traversal as a list of integers
func treeToList(tree Tree) []int {
	var result []int
	traverse(tree, &result)
	return result
}

func traverse(tree Tree, result *[]int) {
	switch t := tree.(type) {
	case Leaf:
		*result = append(*result, t.Value)
	case Node:
		traverse(t.Left, result)
		*result = append(*result, t.Value)
		traverse(t.Right, result)
	}
}

// treeDepth returns the maximum depth of the tree (Leaf has depth 1)
func treeDepth(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return 1
	case Node:
		leftDepth := treeDepth(t.Left)
		rightDepth := treeDepth(t.Right)
		if leftDepth > rightDepth {
			return leftDepth + 1
		}
		return rightDepth + 1
	}
	return 0
}

// Helper functions for operations
func double(x int) int {
	return x * 2
}

func add(acc, x int) int {
	return acc + x
}

// formatList converts a slice of integers to a formatted string like [1, 2, 3]
func formatList(lst []int) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, v := range lst {
		if i > 0 {
			sb.WriteString(", ")
		}
		sb.WriteString(fmt.Sprintf("%d", v))
	}
	sb.WriteString("]")
	return sb.String()
}

func main() {
	// Build the test tree:
	//       4
	//      / \
	//     2   6
	//    / \ / \
	//   1  3 5  7
	tree := Node{
		Left: Node{
			Left:  Leaf{Value: 1},
			Value: 2,
			Right: Leaf{Value: 3},
		},
		Value: 4,
		Right: Node{
			Left:  Leaf{Value: 5},
			Value: 6,
			Right: Leaf{Value: 7},
		},
	}

	// Print results
	fmt.Println(formatList(treeToList(tree)))
	fmt.Println(formatList(treeToList(mapTree(double, tree))))
	fmt.Println(foldTree(add, 0, tree))
	fmt.Println(treeDepth(tree))
}

