  if (tree.type === 'Leaf') {
    return { type: 'Leaf', value: fn(tree.value) };
  } else {
    return {
      type: 'Node',
      left: mapTree(fn, tree.left),
      value: fn(tree.value),
      right: mapTree(fn, tree.right)
    };
  }
}

