  if (tree.type === 'Leaf') {
    return fn(acc, tree.value);
  } else {
    const left = foldTree(fn, acc, tree.left);
    const middle = fn(left, tree.value);
    const right = foldTree(fn, middle, tree.right);
    return right;
  }
}

