from typing import Callable, TypeVar, Union

# Define Tree type using Union for ADT-like behavior
T = TypeVar('T')
U = TypeVar('U')

class Leaf:
    def __init__(self, value: int):
        self.value = value

class Node:
    def __init__(self, left: 'Tree', value: int, right: 'Tree'):
        self.left = left
        self.value = value
        self.right = right

Tree = Union[Leaf, Node]

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply function to all values in tree."""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # isinstance(tree, Node)
        return Node(
            mapTree(fn, tree.left),
            fn(tree.value),
            mapTree(fn, tree.right)
        )

def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """In-order fold over tree values."""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # isinstance(tree, Node)
        left_acc = foldTree(fn, acc, tree.left)
        center_acc = fn(left_acc, tree.value)
        return foldTree(fn, center_acc, tree.right)

def treeToList(tree: Tree) -> list[int]:
    """In-order traversal returning list of integers."""
    result = []

    def inorder(node: Tree):
        if isinstance(node, Leaf):
            result.append(node.value)
        else:  # isinstance(node, Node)
            inorder(node.left)
            result.append(node.value)
            inorder(node.right)

    inorder(tree)
    return result

def treeDepth(tree: Tree) -> int:
    """Return maximum depth of tree (Leaf has depth 1)."""
    if isinstance(tree, Leaf):
        return 1
    else:  # isinstance(tree, Node)
        left_depth = treeDepth(tree.left)
        right_depth = treeDepth(tree.right)
        return 1 + max(left_depth, right_depth)

def double(x: int) -> int:
    return x * 2

def add(a: int, b: int) -> int:
    return a + b

# Create test tree structure:
#       4
#      / \
#     2   6
#    / \ / \
#   1  3 5  7
tree = Node(
    Node(Leaf(1), 2, Leaf(3)),
    4,
    Node(Leaf(5), 6, Leaf(7))
)

# Print results
print(treeToList(tree))
print(treeToList(mapTree(double, tree)))
print(foldTree(add, 0, tree))
print(treeDepth(tree))

