module benchmark/solution

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type MaybeType = Found(Type) | NotFound

type UnifyResult = UOk([(string, Type)]) | UFail

func findSubst(name: string, subst: [(string, Type)]) -> MaybeType =
  match subst {
    [] => NotFound,
    (v, t) :: rest => if v == name then Found(t) else findSubst(name, rest)
  }

export func apply(subst: [(string, Type)], ty: Type) -> Type =
  match ty {
    TVar(name) => match findSubst(name, subst) {
      Found(t) => apply(subst, t),
      NotFound => TVar(name)
    },
    TInt => TInt,
    TBool => TBool,
    TFunc(arg, res) => TFunc(apply(subst, arg), apply(subst, res))
  }

export func unify(t1: Type, t2: Type) -> UnifyResult =
  match t1 {
    TVar(a) => UOk([(a, t2)]),
    TInt => match t2 {
      TInt => UOk([]),
      TVar(a) => UOk([(a, TInt)]),
      _ => UFail
    },
    TBool => match t2 {
      TBool => UOk([]),
      TVar(a) => UOk([(a, TBool)]),
      _ => UFail
    },
    TFunc(a1, r1) => match t2 {
      TVar(a) => UOk([(a, t1)]),
      TFunc(a2, r2) => match unify(a1, a2) {
        UOk(s1) => match unify(r1, r2) {
          UOk(s2) => UOk(s1 ++ s2),
          UFail => UFail
        },
        UFail => UFail
      },
      _ => UFail
    }
  }

func showType(t: Type) -> string =
  match t {
    TVar(name) => name,
    TInt => "TInt",
    TBool => "TBool",
    TFunc(arg, res) => "${showType(arg)} -> ${showType(res)}"
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    UOk(subst) => {
      println("a = ${showType(apply(subst, TVar("a")))}");
      println("b = ${showType(apply(subst, TVar("b")))}")
    },
    UFail => println("fail")
  }
}
